window.docContents[128].resolve({"/5___-Representations-of-finite-groups___-Further-results/5___9___-The-Frobenius-formula-for-the-character-of-an-induced-representation/Alternative-form-of-the-Frobenius-formula/#Chapter5___Remark5___9___2":{"contents":"Remark 5.9.2. If the characteristic of the ground field k is relatively prime to |H|, then this formula can be written as\n\n\\chi(g) = \\frac{1}{|H|} \\sum_{x \\in G : xgx^{-1} \\in H} \\chi_V(xgx^{-1}).\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.9. The Frobenius formula for the character of an induced representation\tAlternative form of the Frobenius formula","header":"Alternative form of the Frobenius formula","id":"/5___-Representations-of-finite-groups___-Further-results/5___9___-The-Frobenius-formula-for-the-character-of-an-induced-representation/Alternative-form-of-the-Frobenius-formula/#Chapter5___Remark5___9___2"},"/9___-Structure-of-finite-dimensional-algebras/9___5___-Blocks/Linked-simple-modules-and-blocks/#Chapter9___Definition9___5___1":{"contents":"Definition 9.5.1. Two simple finite dimensional A-modules X, Y are said to be linked if there is a chain X = M_0, M_1, \\ldots, M_n = Y such that for each i = 0, \\ldots, n - 1 either \\operatorname{Ext}^1(M_i, M_{i+1}) \\neq 0 or \\operatorname{Ext}^1(M_{i+1}, M_i) \\neq 0 (or both).\nHere we agree that X is linked to itself (by a chain of length 0).\n\nThis linking relation is clearly an equivalence relation, so it defines a splitting of the set S of isomorphism classes of simple A-modules into equivalence classes S_k, k \\in B. The kth block \\mathcal{C}_k of \\mathcal{C} is, by definition, the category of all objects M of \\mathcal{C} such that all simple modules occurring in the Jordan-Hölder series of M are in S_k.\n\n\n\n","context":"Introduction to Representation Theory\t9. Structure of finite dimensional algebras\t9.5. Blocks\tLinked simple modules and blocks","header":"Linked simple modules and blocks","id":"/9___-Structure-of-finite-dimensional-algebras/9___5___-Blocks/Linked-simple-modules-and-blocks/#Chapter9___Definition9___5___1"},"/9___-Structure-of-finite-dimensional-algebras/9___5___-Blocks/Section-9___5___-Blocks/#Chapter9___Introduction_9___5":{"contents":"\n\n","context":"Introduction to Representation Theory\t9. Structure of finite dimensional algebras\t9.5. Blocks\tSection 9.5: Blocks","header":"Section 9.5: Blocks","id":"/9___-Structure-of-finite-dimensional-algebras/9___5___-Blocks/Section-9___5___-Blocks/#Chapter9___Introduction_9___5"}});
